selector_to_html = {"a[href=\"#boundaries\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Boundaries<a class=\"headerlink\" href=\"#boundaries\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#compare-candidates-prospectively\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Compare candidates prospectively<a class=\"headerlink\" href=\"#compare-candidates-prospectively\" title=\"Link to this heading\">#</a></h2><p>An incumbent and a candidate model can be compared on the exact same prospectively collected hardware counts. The result reports a conservative finite-shot interval and returns <code class=\"docutils literal notranslate\"><span class=\"pre\">improved</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">degraded</span></code>, or <code class=\"docutils literal notranslate\"><span class=\"pre\">inconclusive</span></code>; it never promotes a model automatically, and no model is promoted without an explicit application decision.</p>", "a[href=\"#qualify-evidence-by-topology-and-depth\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Qualify evidence by topology and depth<a class=\"headerlink\" href=\"#qualify-evidence-by-topology-and-depth\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">TwinCircuitSupport</span></code> narrows a statistical envelope to the directed physical couplers and maximum circuit depth that were actually validated. It does not infer support merely because a coupler exists on the device, and it fails closed for untested interactions, reversed directions, excessive depth, or operations of arity greater than two.</p><p>Overlapping contemporaneous cells from one QPU can be composed into a connected-region coverage report for circuit-mapping checks, preserving directed edges and conservative limits. Local statistical bounds are never combined into a region-level accuracy claim.</p>", "a[href=\"#validate-against-hardware\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Validate against hardware<a class=\"headerlink\" href=\"#validate-against-hardware\" title=\"Link to this heading\">#</a></h2><p>The validation workflow is deliberately explicit and resumable:</p>", "a[href=\"#track-drift-over-time\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Track drift over time<a class=\"headerlink\" href=\"#track-drift-over-time\" title=\"Link to this heading\">#</a></h2><p>Calibration drift and prediction accuracy can be aligned across chronological snapshots for the same fixed circuits, so a chart-ready series of Twin\u2194QPU agreement, reference agreement, repeatability, and verified bounds is available without claiming causality or choosing a promotion policy. Histories persist offline with private permissions and refuse destructive replacement.</p>", "a[href=\"#qpu-digital-twin\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">QPU Digital Twin<a class=\"headerlink\" href=\"#qpu-digital-twin\" title=\"Link to this heading\">#</a></h1><p>A digital twin is a calibration-conditioned model of one QPU. It predicts the measurement distribution you would see on hardware, and it keeps that prediction tied to evidence: which circuits were validated, on which physical couplers, at which depth, at which calibration snapshot, and with which confidence bound.</p>", "a[href=\"#what-a-prediction-is\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">What a prediction is<a class=\"headerlink\" href=\"#what-a-prediction-is\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#build-a-twin-for-any-qpu\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Build a Twin for any QPU<a class=\"headerlink\" href=\"#build-a-twin-for-any-qpu\" title=\"Link to this heading\">#</a></h2><p>Start from a <code class=\"docutils literal notranslate\"><span class=\"pre\">NoiseModel</span></code> carrying a device profile. The execution target and the ordered physical mapping become part of the immutable Twin identity:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
